CREATE OR REPLACE PROCEDURE sp(para_Budgeted integer, para_total_budget_percent_invested real, para_Budget_invested_percent text, para_total_budget_percent_budgeted real) LANGUAGE plpgsql AS $$
DECLARE
  total_sum NUMERIC;
BEGIN
  SELECT SUM("Budgeted") INTO total_sum FROM "budget";
  IF total_sum <= para_Budgeted THEN
    UPDATE "budget" SET "total_budget_percent_invested" = para_total_budget_percent_invested WHERE "Budget_invested_percent" = para_Budget_invested_percent;
    UPDATE "budget" SET "Invested" = ROUND(("Budgeted"::numeric * para_total_budget_percent_invested::numeric) / 100, 0)::integer WHERE "Budget_invested_percent" = para_Budget_invested_percent;
    UPDATE "budget" SET "Budgeted" = "Invested" WHERE "Budget_invested_percent" = para_Budget_invested_percent AND "Invested" > "Budgeted";
    UPDATE "budget" SET "Budget_invested_percent" = CASE WHEN "Budgeted" = 0 THEN '0.0' ELSE ROUND(("Invested"::numeric * 100) / "Budgeted", 1)::text END WHERE "Budget_invested_percent" = para_Budget_invested_percent;
  ELSE
    DELETE FROM "budget" WHERE "total_budget_percent_budgeted" < para_total_budget_percent_budgeted;
    SELECT SUM("Budgeted") INTO total_sum FROM "budget";
    UPDATE "budget" SET "total_budget_percent_budgeted" = CASE WHEN total_sum IS NULL OR total_sum = 0 THEN 0::real ELSE ROUND(("Budgeted"::numeric * 100) / total_sum, 1)::real END;
    UPDATE "budget" SET "Budget_invested_percent" = CASE WHEN "Budgeted" = 0 THEN '0.0' ELSE ROUND(("Invested"::numeric * 100) / "Budgeted", 1)::text END;
  END IF;
  UPDATE "budget" SET "total_budget_percent_invested" = 0::real WHERE "Invested" = 0;
END;
$$;

